"""Penjelasan tambahan halaman kalkulator · Regresi bagian 1 (linear sampai PLS, 18 metode)."""
from .metode_extra import X

X("regresi-linear-sederhana-berganda",
  "Dinas pertanian ingin mengetahui berapa tambahan hasil jagung untuk setiap tambahan 10 kg pupuk N dan setiap tambahan 10 mm curah hujan, dari data 40 petani. Regresi linear berganda menaksir pengaruh masing-masing prediktor sambil mengendalikan yang lain, lalu dapat dipakai untuk memprediksi hasil pada kombinasi pupuk dan hujan tertentu.",
  ["Satu baris per pengamatan; kolom Y dan satu atau lebih kolom X numerik.",
   "Prediktor kategorik (misalnya varietas) lebih tepat dianalisis dengan kalkulator regresi dummy.",
   "Biarkan intersep tercentang kecuali ada alasan teori yang kuat bahwa garis harus melewati titik nol."],
  [("Ringkasan model", "R² menunjukkan proporsi keragaman Y yang dijelaskan; R² terkoreksi menghukum prediktor yang tidak berguna. Galat baku regresi (s) adalah ukuran rata-rata kesalahan prediksi dalam satuan Y."),
   ("Tabel koefisien", "Setiap koefisien adalah perubahan rata-rata Y per satu satuan X, dengan prediktor lain tetap. Uji t dan P-value menguji apakah koefisien berbeda dari nol."),
   ("ANOVA regresi", "Uji F menguji apakah semua koefisien kemiringan sekaligus nol, yaitu apakah model berguna sama sekali."),
   ("Matriks korelasi dan VIF", "Korelasi antarprediktor yang tinggi (VIF di atas sekitar 10) membuat koefisien tidak stabil."),
   ("Uji asumsi dan prediksi", "Periksa normalitas galat, kehomogenan ragam, dan autokorelasi. Tab Prediksi menghitung nilai dugaan untuk nilai X baru beserta selangnya.")],
  ["Menafsirkan koefisien sebagai hubungan sebab-akibat dari data pengamatan.",
   "Memprediksi jauh di luar rentang X yang diamati (ekstrapolasi).",
   "Hanya melihat R² tanpa memeriksa plot galat.",
   "Membuang prediktor hanya karena tidak nyata padahal penting secara teori."],
  "Contoh kalimat: “Model regresi berganda nyata (F(2; 37) = 41,3; P < 0,001; R² terkoreksi = 0,68). Setiap tambahan 10 kg N/ha meningkatkan hasil rata-rata 0,21 t/ha (P < 0,001), dengan curah hujan dikendalikan.”",
  [("Berapa jumlah data minimal?", "Aturan praktis sekitar 10–20 pengamatan per prediktor agar koefisien cukup stabil."),
   ("Apakah Y harus normal?", "Yang diasumsikan normal adalah galatnya, bukan Y. Dengan sampel besar, pelanggaran ringan tidak terlalu berpengaruh pada uji koefisien.")])

X("regresi-dummy",
  "Seorang peneliti ingin membandingkan gaji karyawan dari tiga departemen sambil mengendalikan lama kerja. Departemen adalah variabel kategorik, sehingga diubah menjadi variabel dummy (0/1), dengan satu departemen sebagai kategori acuan. Model ini menggabungkan logika ANOVA dan regresi dalam satu persamaan.",
  ["Kolom Y, satu atau lebih kolom X numerik, dan satu atau lebih kolom kategorik.",
   "Kategori ditulis sebagai teks atau kode; kalkulator membuat dummy secara otomatis dengan kategori pertama sebagai acuan.",
   "Pastikan setiap kategori punya cukup pengamatan."],
  [("Koefisien dummy", "Selisih rata-rata Y antara kategori itu dan kategori acuan, pada nilai X numerik yang sama."),
   ("Koefisien numerik", "Perubahan Y per satuan X, diasumsikan sama di semua kategori (garis sejajar)."),
   ("Uji F parsial", "Menguji seluruh dummy dari satu variabel kategorik sekaligus; inilah uji yang tepat untuk pertanyaan “apakah departemen berpengaruh?”."),
   ("Grafik", "Garis regresi per kategori; jarak vertikal antargaris adalah koefisien dummy.")],
  ["Memasukkan semua kategori sebagai dummy bersama intersep (jebakan dummy), sehingga model tidak dapat ditaksir.",
   "Memberi kode 1, 2, 3 pada kategori lalu memperlakukannya sebagai angka.",
   "Menyimpulkan suatu kategori tidak berbeda hanya dari satu uji t dummy, padahal pertanyaannya tentang variabel secara keseluruhan."],
  "Contoh kalimat: “Setelah dikendalikan lama kerja, departemen berpengaruh nyata terhadap gaji (uji F parsial: F(2; 56) = 7,4; P < 0,01). Karyawan departemen TI bergaji rata-rata Rp1,2 juta lebih tinggi daripada departemen administrasi (acuan).”",
  [("Bagaimana memilih kategori acuan?", "Pilih kategori yang paling bermakna sebagai pembanding, misalnya kontrol atau kelompok terbesar. Hasil uji keseluruhan tidak berubah."),
   ("Bagaimana bila kemiringan berbeda antarkategori?", "Tambahkan interaksi dummy × X; tanpa itu, model mengandaikan garis sejajar.")])

X("regresi-polinomial",
  "Hasil tanaman naik seiring dosis pupuk, tetapi pada dosis tinggi justru menurun karena keracunan. Garis lurus tidak dapat menangkap pola naik-lalu-turun ini. Regresi polinomial kuadratik menambahkan suku X², sehingga dosis optimum dapat dihitung dari titik puncak kurva.",
  ["Kolom X dan Y numerik; sebaiknya ada cukup banyak taraf X yang berbeda (minimal derajat + 2).",
   "Pilih derajat: 2 untuk satu lengkungan, 3 untuk kurva berbentuk S. Derajat lebih tinggi jarang diperlukan.",
   "Centang “pusatkan X” untuk mengurangi korelasi antara X dan X², tanpa mengubah kurva."],
  [("Koefisien", "Koefisien X² negatif berarti kurva cekung ke bawah (ada maksimum); positif berarti cekung ke atas (ada minimum)."),
   ("Pemilihan derajat", "Bandingkan R² terkoreksi, AIC, atau uji suku tertinggi. Naikkan derajat hanya bila suku tambahan nyata."),
   ("Titik optimum", "Untuk model kuadratik, X optimum = −b₁/(2b₂). Pastikan berada di dalam rentang data."),
   ("Grafik", "Kurva dugaan dengan pita kepercayaan; pita melebar di ujung menunjukkan ketidakpastian ekstrapolasi.")],
  ["Memakai derajat tinggi sehingga kurva mengikuti derau dan bergoyang liar di ujung.",
   "Menafsirkan koefisien X sendirian; dalam polinomial, pengaruh X bergantung pada nilai X.",
   "Melaporkan titik optimum di luar rentang dosis yang diuji."],
  "Contoh kalimat: “Hubungan dosis pupuk dan hasil mengikuti model kuadratik (Y = 3,2 + 0,048X − 0,00016X²; R² = 0,91). Dosis optimum diperkirakan 150 kg/ha dengan hasil maksimum 6,8 t/ha.”",
  [("Mengapa X perlu dipusatkan?", "X dan X² sangat berkorelasi; pemusatan mengurangi kolinearitas sehingga galat baku koefisien lebih stabil. Kurva dan prediksinya tetap sama."),
   ("Kapan sebaiknya memakai spline atau regresi nonlinear?", "Bila bentuk kurva tidak cocok dengan parabola, misalnya naik lalu mendatar (plateau), model nonlinear atau spline biasanya lebih tepat.")])

X("diagnostik-regresi-tanpa-intersep",
  "Setelah membuat model regresi untuk harga rumah, seorang analis perlu memastikan model itu layak dipercaya sebelum dipakai: apakah galatnya normal, apakah ragam galat membesar pada rumah mahal, apakah ada prediktor yang saling tumpang tindih, dan apakah ada satu dua rumah yang menarik garis secara berlebihan. Kalkulator ini menjalankan semua diagnostik itu sekaligus, dan juga dapat menyesuaikan model tanpa intersep bila teori menuntutnya.",
  ["Kolom Y dan kolom X numerik, sama seperti regresi linear.",
   "Untuk uji autokorelasi, urutkan baris sesuai urutan waktu atau urutan pengumpulan data.",
   "Hilangkan centang intersep hanya bila Y pasti nol ketika semua X nol (misalnya biaya total terhadap jumlah unit)."],
  [("Normalitas galat", "Uji Shapiro–Wilk dan plot Q-Q. Titik yang menyimpang di ujung menandakan ekor berat atau outlier."),
   ("Homoskedastisitas", "Uji Breusch–Pagan; P kecil berarti ragam galat tidak konstan. Pertimbangkan transformasi log atau galat baku robust."),
   ("Autokorelasi", "Statistik Durbin–Watson; nilai jauh dari 2 menandakan galat berurutan saling berkaitan."),
   ("Multikolinearitas (VIF)", "VIF di atas sekitar 10 (sebagian memakai 5) menandakan prediktor tumpang tindih."),
   ("Pengamatan berpengaruh", "Leverage, residual terstudentkan, dan jarak Cook. Cook’s D yang besar (misalnya di atas 4/n) menandai titik yang perlu diperiksa.")],
  ["Menghapus pengamatan berpengaruh tanpa alasan substantif.",
   "Menghilangkan intersep hanya karena intersep tidak nyata.",
   "Membandingkan R² model tanpa intersep dengan model berintersep; rumus R²-nya berbeda sehingga tidak sebanding."],
  "Contoh kalimat: “Diagnostik model tidak menunjukkan pelanggaran asumsi yang berarti: galat menyebar normal (Shapiro–Wilk P = 0,42), ragam homogen (Breusch–Pagan P = 0,31), dan seluruh VIF di bawah 3. Satu pengamatan memiliki jarak Cook 0,52; analisis tanpa pengamatan tersebut memberikan kesimpulan yang sama.”",
  [("Apa yang dilakukan bila asumsi dilanggar?", "Transformasi Y atau X, galat baku robust, regresi robust untuk outlier, atau GLM bila Y berupa cacahan atau proporsi."),
   ("Mengapa R² model tanpa intersep sering sangat tinggi?", "Karena dihitung terhadap nol, bukan terhadap rata-rata Y; angka itu tidak bisa dibandingkan dengan R² biasa.")])

X("regresi-nonlinear",
  "Pertumbuhan bobot ayam broiler mengikuti kurva S: lambat di awal, cepat di tengah, lalu mendatar mendekati bobot dewasa. Model logistik atau Gompertz memiliki parameter yang bermakna langsung, misalnya bobot asimtot dan laju pertumbuhan, sesuatu yang tidak diberikan oleh polinomial.",
  ["Kolom X (misalnya umur) dan Y (misalnya bobot).",
   "Pilih model yang sesuai bentuk data: eksponensial, logistik, Gompertz, Michaelis–Menten, dan lainnya.",
   "Data sebaiknya mencakup seluruh bagian kurva, termasuk daerah mendatar; tanpa itu, asimtot sulit ditaksir."],
  [("Tabel parameter", "Nilai dugaan, galat baku, dan selang kepercayaan setiap parameter. Parameter dengan selang sangat lebar menandakan data kurang informatif."),
   ("Perbandingan model", "AIC dan galat baku sisaan untuk beberapa model; pilih yang AIC-nya terkecil dan bentuknya masuk akal secara biologis."),
   ("Grafik", "Kurva dugaan dan titik data; periksa bagian awal dan akhir kurva."),
   ("Interpretasi", "Ringkasan arti parameter dalam bahasa sehari-hari.")],
  ["Memilih model hanya karena R² tertinggi tanpa melihat makna parameternya.",
   "Data tidak mencapai fase mendatar tetapi tetap melaporkan asimtot sebagai fakta.",
   "Memakai R² seperti pada regresi linear; pada model nonlinear R² tidak selalu bermakna sama."],
  "Contoh kalimat: “Model Gompertz memberikan kesesuaian terbaik (AIC terkecil). Bobot dewasa diduga 3,42 kg (SE 0,08) dengan laju pertumbuhan maksimum dicapai pada umur 24 hari.”",
  [("Mengapa model kadang gagal konvergen?", "Nilai awal parameter terlalu jauh, data tidak mencakup seluruh kurva, atau model terlalu rumit untuk data yang ada."),
   ("Kapan nonlinear lebih baik daripada transformasi log?", "Bila galat aditif pada skala asli, atau parameter yang bermakna hanya ada pada bentuk nonlinear.")])

X("regresi-logistik-biner",
  "Rumah sakit ingin memperkirakan peluang pasien mengalami komplikasi (ya/tidak) berdasarkan umur, kadar gula darah, dan riwayat merokok. Respon biner tidak cocok dengan regresi linear karena peluang harus berada di antara 0 dan 1. Regresi logistik memodelkan log-odds, dan hasilnya disampaikan sebagai rasio odds.",
  ["Kolom Y berisi dua kategori (0/1, ya/tidak); kalkulator menentukan kategori “sukses”.",
   "Kolom X numerik dan kolom kategorik (dijadikan dummy).",
   "Atur titik potong klasifikasi (biasanya 0,5) bila ingin mengubah keseimbangan sensitivitas dan spesifisitas."],
  [("Koefisien dan rasio odds", "e^β adalah rasio odds: berapa kali odds kejadian berubah per satuan X. OR > 1 menaikkan peluang, OR < 1 menurunkan."),
   ("Ukuran kecocokan", "Deviance, AIC, dan pseudo-R² (McFadden, Nagelkerke). Pseudo-R² lebih kecil daripada R² regresi linear dan tidak ditafsirkan sama."),
   ("Uji Hosmer–Lemeshow", "P di atas 0,05 berarti tidak ada bukti model kurang cocok."),
   ("Tabel klasifikasi", "Akurasi, sensitivitas, spesifisitas, dan AUC (luas di bawah kurva ROC). AUC 0,7–0,8 cukup, di atas 0,8 baik.")],
  ["Menafsirkan koefisien sebagai perubahan peluang; koefisien adalah perubahan log-odds.",
   "Terlalu sedikit kejadian per prediktor (kurang dari sekitar 10), sehingga dugaan tidak stabil.",
   "Hanya melaporkan akurasi pada data yang tidak seimbang; akurasi 95% bisa diperoleh dengan selalu menebak “tidak”."],
  "Contoh kalimat: “Setiap kenaikan 10 mg/dL gula darah meningkatkan odds komplikasi sebesar 1,35 kali (OR = 1,35; IK 95%: 1,12–1,63; P = 0,002), dengan umur dan status merokok dikendalikan. Model memiliki AUC 0,81.”",
  [("Apa beda odds dan peluang?", "Odds = p/(1 − p). Peluang 0,8 sama dengan odds 4. Untuk kejadian langka, OR mendekati rasio risiko."),
   ("Bagaimana bila terjadi pemisahan sempurna?", "Bila suatu prediktor memisahkan 0 dan 1 secara sempurna, koefisien membesar tanpa batas. Gabungkan kategori, kurangi prediktor, atau gunakan regresi logistik Firth.")])

X("regresi-probit",
  "Dalam uji toksisitas insektisida, kematian serangga (mati/hidup) diamati pada beberapa dosis. Model probit mengandaikan setiap serangga punya ambang toleransi yang menyebar normal, sehingga dari kurvanya dapat dihitung LD50, yaitu dosis yang membunuh separuh populasi.",
  ["Kolom Y biner (0/1) per individu, kolom X numerik (misalnya log dosis), dan kolom kategorik bila ada.",
   "Untuk uji dosis-respon, sebaiknya gunakan logaritma dosis sebagai X.",
   "Atur titik potong klasifikasi bila perlu."],
  [("Koefisien", "Perubahan nilai z (skala normal baku) per satuan X. Tanda koefisien sama artinya dengan logistik."),
   ("Efek marginal", "Perubahan peluang per satuan X = β·φ(xβ); terbesar di sekitar peluang 0,5."),
   ("Dosis efektif", "LD50 = −β₀/β₁ pada skala X. Bila X adalah log dosis, kembalikan dengan antilog."),
   ("Kecocokan dan klasifikasi", "Dibaca seperti regresi logistik: deviance, AIC, Hosmer–Lemeshow, dan tabel klasifikasi.")],
  ["Membandingkan besar koefisien probit dan logit secara langsung; koefisien logit kira-kira 1,6–1,8 kali koefisien probit.",
   "Memakai dosis asli padahal hubungan linear pada log dosis.",
   "Melaporkan LD50 tanpa selang kepercayaan."],
  "Contoh kalimat: “Analisis probit menghasilkan LD50 sebesar 2,4 ppm (IK 95%: 1,9–3,0 ppm). Kemiringan garis probit 2,8 menunjukkan respon populasi yang relatif seragam terhadap insektisida.”",
  [("Probit atau logit?", "Hasil keduanya hampir selalu serupa. Probit lazim di toksikologi dan bila ada teori ambang normal; logit lebih mudah ditafsirkan lewat rasio odds."),
   ("Bagaimana bila ada kematian pada kontrol?", "Koreksi dengan rumus Abbott sebelum analisis, atau masukkan parameter kematian alami ke model.")])

X("regresi-logistik-multinomial",
  "Seorang peneliti pemasaran mempelajari pilihan konsumen terhadap tiga merek sabun berdasarkan umur dan pendapatan. Responnya berupa kategori tanpa urutan, sehingga regresi logistik multinomial membandingkan setiap merek dengan satu merek acuan.",
  ["Kolom Y berisi tiga atau lebih kategori tanpa urutan.",
   "Kolom X numerik dan kategorik.",
   "Setiap kategori Y perlu cukup banyak pengamatan; kategori yang sangat jarang membuat dugaan tidak stabil."],
  [("Koefisien", "Satu set koefisien untuk setiap kategori dibandingkan kategori acuan. e^β adalah rasio odds relatif: odds memilih kategori itu dibanding acuan per satuan X."),
   ("Matriks konfusi", "Seberapa sering model menebak kategori yang benar; diagonal yang besar berarti klasifikasi baik."),
   ("Peluang prediksi", "Peluang setiap kategori untuk setiap pengamatan; jumlahnya selalu 1.")],
  ["Memakai model multinomial untuk kategori yang sebenarnya berurutan; model ordinal lebih hemat dan lebih kuat.",
   "Menafsirkan koefisien tanpa menyebut kategori acuan.",
   "Mengabaikan asumsi IIA (kebebasan dari alternatif yang tidak relevan) bila kategorinya sangat mirip."],
  "Contoh kalimat: “Dibandingkan merek A (acuan), setiap kenaikan pendapatan Rp1 juta meningkatkan odds memilih merek C sebesar 1,42 kali (P < 0,01), sedangkan pengaruhnya terhadap pilihan merek B tidak nyata.”",
  [("Bagaimana memilih kategori acuan?", "Pilih kategori yang paling bermakna sebagai pembanding atau yang paling sering muncul; peluang prediksi tidak berubah."),
   ("Apa itu asumsi IIA?", "Rasio peluang dua pilihan tidak bergantung pada ada atau tidaknya pilihan lain. Bila dua pilihan saling menggantikan, asumsi ini bisa dilanggar.")])

X("regresi-logistik-ordinal",
  "Kepuasan pelanggan diukur dengan skala 1 (sangat tidak puas) sampai 4 (sangat puas), lalu dihubungkan dengan lama tunggu dan keramahan petugas. Kategorinya berurutan tetapi jaraknya tidak tentu sama, sehingga regresi linear kurang tepat. Model odds proporsional memakai satu set koefisien dan beberapa ambang.",
  ["Kolom Y berisi kategori berurutan, dikodekan sebagai angka (1, 2, 3, …) atau teks yang urutannya jelas.",
   "Kolom X numerik.",
   "Setiap kategori Y sebaiknya cukup terisi; kategori yang hampir kosong sebaiknya digabung."],
  [("Koefisien", "e^β adalah rasio odds kumulatif: odds berada pada kategori yang lebih tinggi per satuan X, sama untuk setiap titik potong."),
   ("Ambang (threshold)", "Batas pada skala laten tempat kategori berpindah; bukan parameter yang biasa ditafsirkan sendiri."),
   ("Matriks konfusi", "Kecocokan kategori dugaan dengan kategori teramati."),
   ("Grafik peluang", "Peluang setiap kategori sebagai fungsi X; berguna untuk menjelaskan hasil kepada pembaca awam.")],
  ["Menganalisis skala Likert sebagai angka dengan regresi linear biasa tanpa pertimbangan.",
   "Tidak memeriksa asumsi odds proporsional (uji Brant).",
   "Memakai model multinomial sehingga informasi urutan terbuang."],
  "Contoh kalimat: “Setiap penambahan 5 menit waktu tunggu menurunkan odds berada pada kategori kepuasan yang lebih tinggi sebesar 28% (OR = 0,72; IK 95%: 0,61–0,85).”",
  [("Apa itu asumsi odds proporsional?", "Pengaruh X sama untuk semua titik potong (1 lawan 2–4, 1–2 lawan 3–4, dan seterusnya). Bila dilanggar, gunakan model odds proporsional parsial atau multinomial."),
   ("Bolehkah skala Likert dianalisis dengan regresi linear?", "Untuk skor gabungan dari banyak butir sering dapat diterima; untuk satu butir dengan sedikit kategori, model ordinal lebih tepat.")])

X("regresi-poisson",
  "Dinas kesehatan memodelkan jumlah kasus demam berdarah per kecamatan per bulan berdasarkan curah hujan dan kepadatan penduduk. Responnya berupa cacahan (0, 1, 2, …), tidak pernah negatif, dan ragamnya cenderung naik seiring rata-rata. Regresi Poisson dengan penghubung log cocok untuk data seperti ini.",
  ["Kolom Y berisi bilangan cacah tidak negatif.",
   "Kolom X numerik dan kategorik.",
   "Bila waktu atau luas pengamatan berbeda-beda, ingat bahwa yang sebenarnya dimodelkan adalah laju; pertimbangkan memasukkan log paparan sebagai prediktor."],
  [("Koefisien dan rasio laju", "e^β adalah rasio laju (IRR): berapa kali rata-rata cacahan berubah per satuan X."),
   ("Ukuran kecocokan", "Deviance dan AIC; deviance yang jauh lebih besar dari derajat bebasnya menandakan masalah."),
   ("Uji overdispersi", "Rasio dispersi jauh di atas 1 berarti ragam lebih besar daripada rata-rata. Galat baku Poisson menjadi terlalu kecil; beralihlah ke binomial negatif atau quasi-Poisson."),
   ("Nilai aktual dan prediksi", "Bandingkan juga banyaknya nol teramati dengan yang diharapkan model.")],
  ["Mengabaikan overdispersi sehingga terlalu banyak koefisien tampak nyata.",
   "Memakai regresi linear untuk cacahan kecil dengan banyak nol.",
   "Membandingkan cacahan dari periode pengamatan yang berbeda panjangnya tanpa offset."],
  "Contoh kalimat: “Setiap kenaikan 50 mm curah hujan bulanan meningkatkan laju kasus DBD sebesar 18% (IRR = 1,18; IK 95%: 1,09–1,28). Rasio dispersi 1,1 menunjukkan model Poisson memadai.”",
  [("Kapan beralih ke binomial negatif?", "Bila rasio dispersi jelas di atas 1 (misalnya lebih dari 1,5) atau uji overdispersi nyata."),
   ("Bagaimana bila terlalu banyak nol?", "Pertimbangkan model zero-inflated atau hurdle, yang memisahkan proses “tidak mungkin terjadi” dari proses cacahan.")])

X("regresi-binomial-negatif",
  "Peneliti hama menghitung jumlah wereng per rumpun padi pada berbagai varietas. Sebagian besar rumpun berisi sedikit wereng, tetapi beberapa rumpun berisi puluhan; ragamnya jauh melebihi rata-rata. Regresi binomial negatif menambahkan parameter dispersi sehingga galat bakunya jujur.",
  ["Kolom Y berupa cacahan tidak negatif.",
   "Kolom X numerik dan kategorik.",
   "Biasanya dipakai setelah regresi Poisson menunjukkan overdispersi."],
  [("Koefisien dan rasio laju", "Ditafsirkan sama seperti Poisson: e^β adalah rasio rata-rata cacahan per satuan X."),
   ("Parameter dispersi", "θ (atau α = 1/θ) mengukur keragaman tambahan. θ kecil berarti overdispersi besar."),
   ("Ukuran kecocokan", "Bandingkan AIC dengan model Poisson; selisih besar mendukung binomial negatif."),
   ("Nilai aktual dan prediksi", "Periksa apakah pengamatan ekstrem masih masuk akal di bawah model.")],
  ["Tetap memakai Poisson walaupun overdispersi jelas.",
   "Menganggap koefisien binomial negatif “lebih kecil pengaruhnya” karena galat bakunya lebih besar; besarnya pengaruh biasanya serupa, hanya ketidakpastiannya yang jujur.",
   "Lupa melaporkan parameter dispersi."],
  "Contoh kalimat: “Data cacahan wereng menunjukkan overdispersi (rasio dispersi Poisson = 6,3), sehingga digunakan regresi binomial negatif (θ = 1,4). Varietas tahan menurunkan rata-rata populasi wereng sebesar 64% (IRR = 0,36; P < 0,001).”",
  [("Apa beda NB1 dan NB2?", "NB2 (bawaan kebanyakan perangkat lunak) mengandaikan ragam = μ + μ²/θ; NB1 mengandaikan ragam sebanding dengan μ."),
   ("Bagaimana bila masih banyak nol berlebih?", "Coba model zero-inflated binomial negatif (ZINB) atau hurdle.")])

X("regresi-gamma",
  "Biaya rawat inap pasien selalu positif, sangat menceng ke kanan, dan pasien dengan rata-rata biaya tinggi juga lebih bervariasi. Regresi linear biasa sering memberi prediksi negatif dan galat yang tidak homogen. GLM gamma dengan penghubung log memodelkan rata-rata biaya secara langsung, dengan ragam yang naik sebanding kuadrat rata-rata.",
  ["Kolom Y berisi nilai positif (tidak boleh nol atau negatif).",
   "Kolom X numerik dan kategorik.",
   "Bila ada banyak nol, gunakan model dua bagian atau Tweedie."],
  [("Koefisien", "Dengan penghubung log, e^β adalah rasio rata-rata Y per satuan X."),
   ("Parameter dispersi dan CV", "Dispersi φ; akar φ adalah koefisien variasi yang dianggap konstan."),
   ("Ukuran kecocokan", "Deviance dan AIC untuk membandingkan model."),
   ("Nilai aktual dan prediksi", "Prediksi selalu positif, berbeda dengan regresi linear.")],
  ["Memasukkan nilai nol ke model gamma.",
   "Menafsirkan e^β sebagai selisih rupiah; itu adalah rasio.",
   "Membandingkan hasil dengan regresi log-Y tanpa sadar bahwa keduanya menaksir rata-rata yang berbeda (aritmetik lawan geometrik)."],
  "Contoh kalimat: “Dengan GLM gamma (penghubung log), pasien dengan komorbid memiliki rata-rata biaya rawat inap 1,58 kali pasien tanpa komorbid (IK 95%: 1,31–1,90), setelah dikendalikan umur dan lama rawat.”",
  [("Gamma atau regresi log Y?", "Gamma menaksir log rata-rata aritmetik secara langsung; regresi log Y menaksir rata-rata geometrik. Untuk total biaya, gamma lebih tepat."),
   ("Bagaimana bila ragam naik lebih cepat lagi?", "Pertimbangkan sebaran Gaussian invers atau Tweedie.")])

X("seleksi-variabel",
  "Seorang mahasiswa memiliki 12 calon prediktor untuk menjelaskan produktivitas lahan, padahal datanya hanya 60 pengamatan. Memasukkan semuanya membuat model tidak stabil dan sulit ditafsirkan. Seleksi variabel membantu menemukan himpunan prediktor yang ringkas, dengan catatan bahwa hasilnya adalah alat bantu, bukan kebenaran mutlak.",
  ["Kolom Y dan semua calon prediktor X numerik.",
   "Pilih metode (maju, mundur, bertahap) dan kriteria (AIC, BIC, atau P-value).",
   "Sebaiknya calon prediktor sudah disaring dulu berdasarkan teori."],
  [("Koefisien model terpilih", "Koefisien dan uji untuk prediktor yang lolos seleksi; P-value ini cenderung terlalu optimistis karena variabel dipilih memakai data yang sama."),
   ("Riwayat seleksi", "Urutan prediktor yang masuk atau keluar beserta kriterianya; berguna untuk melihat seberapa dekat keputusan antartahap."),
   ("Perbandingan dengan model penuh", "AIC, BIC, dan R² terkoreksi model terpilih dibanding model dengan semua prediktor."),
   ("VIF", "Memeriksa apakah model terpilih masih mengandung prediktor yang tumpang tindih.")],
  ["Menganggap model terpilih sebagai satu-satunya model benar.",
   "Melaporkan P-value model terpilih seolah-olah model ditentukan sebelum melihat data.",
   "Membuang prediktor yang penting secara teori hanya karena kriteria statistik."],
  "Contoh kalimat: “Seleksi bertahap berbasis AIC memilih empat dari dua belas calon prediktor (AIC = 182,4 dibanding 189,7 pada model penuh). Karena seleksi otomatis cenderung melebih-lebihkan signifikansi, hasil ini diperlakukan sebagai eksploratif.”",
  [("AIC atau BIC?", "AIC cenderung memilih model yang sedikit lebih besar dan cocok untuk prediksi; BIC memilih model lebih ringkas dan cocok bila tujuannya mencari model sederhana."),
   ("Apa alternatif yang lebih baik?", "Regularisasi (LASSO, elastic net) dengan validasi silang, atau model yang ditentukan dari teori lalu dievaluasi dengan validasi silang.")])

X("regresi-ridge",
  "Data spektroskopi atau data ekonomi sering memiliki prediktor yang sangat berkorelasi; misalnya pendapatan, pengeluaran, dan aset rumah tangga. Koefisien OLS menjadi sangat besar, berganti tanda, dan berubah drastis bila satu data diganti. Regresi ridge menyusutkan koefisien ke arah nol sehingga lebih stabil dan prediksinya lebih baik pada data baru.",
  ["Kolom Y dan dua atau lebih kolom X numerik.",
   "Kalkulator membakukan prediktor secara otomatis sebelum penalti diterapkan.",
   "Biarkan λ dipilih otomatis dengan validasi silang, kecuali ingin membandingkan beberapa nilai λ."],
  [("Koefisien", "Koefisien ridge pada skala asli prediktor; umumnya lebih kecil dan lebih seimbang daripada OLS."),
   ("Perbandingan dengan OLS", "Menunjukkan seberapa jauh penyusutan terjadi dan prediktor mana yang paling terdampak kolinearitas."),
   ("Jalur validasi silang", "Galat prediksi untuk berbagai λ; λ terpilih memberi galat terkecil atau dalam satu galat baku dari minimum."),
   ("Nilai aktual dan prediksi", "Untuk menilai kecocokan model.")],
  ["Berharap ridge memilih variabel; ridge tidak pernah membuat koefisien tepat nol.",
   "Menafsirkan P-value seperti OLS; koefisien ridge bias secara sengaja.",
   "Tidak membakukan prediktor (kalkulator ini sudah melakukannya)."],
  "Contoh kalimat: “Karena prediktor sangat berkorelasi (VIF hingga 34), digunakan regresi ridge dengan λ = 0,42 yang dipilih melalui validasi silang 10 lipatan. Galat prediksi validasi silang turun 18% dibandingkan OLS.”",
  [("Ridge atau LASSO?", "Ridge bila semua prediktor kemungkinan berpengaruh kecil dan saling berkorelasi; LASSO bila diyakini hanya sedikit prediktor yang penting."),
   ("Mengapa koefisien bias malah lebih baik?", "Karena penurunan ragam jauh lebih besar daripada kenaikan bias, sehingga galat kuadrat rata-rata total lebih kecil.")])

X("regresi-lasso",
  "Seorang analis memiliki 30 indikator ekonomi untuk memprediksi inflasi bulanan dan menduga hanya sebagian kecil yang benar-benar penting. LASSO menyusutkan koefisien dan membuat sebagian tepat nol, sehingga sekaligus melakukan seleksi variabel dan menghasilkan model yang ringkas.",
  ["Kolom Y dan banyak kolom X numerik; jumlah X boleh mendekati atau melebihi jumlah pengamatan.",
   "Prediktor dibakukan secara otomatis.",
   "λ dipilih otomatis dengan validasi silang; nilai yang lebih besar menghasilkan model lebih ringkas."],
  [("Koefisien", "Prediktor dengan koefisien nol dikeluarkan dari model. Koefisien yang tersisa tertarik ke arah nol (bias)."),
   ("Perbandingan dengan OLS", "Menunjukkan prediktor mana yang dibuang dan seberapa besar penyusutan."),
   ("Jalur validasi silang", "Galat untuk berbagai λ; aturan satu galat baku memberi model yang lebih sederhana dengan kinerja hampir sama."),
   ("Nilai aktual dan prediksi", "Kecocokan model terhadap data.")],
  ["Melaporkan P-value OLS untuk variabel yang dipilih LASSO seolah-olah tanpa seleksi.",
   "Menganggap variabel yang tidak terpilih pasti tidak berpengaruh; dari sekelompok prediktor yang sangat berkorelasi, LASSO sering hanya memilih satu secara acak.",
   "Memakai hasil satu kali validasi silang tanpa sadar bahwa pilihan variabel bisa berubah bila pembagian data berubah."],
  "Contoh kalimat: “LASSO dengan λ yang dipilih melalui validasi silang 10 lipatan (aturan satu galat baku) mempertahankan 6 dari 30 indikator. Harga pangan dan nilai tukar memiliki koefisien terbesar.”",
  [("Mengapa LASSO bisa membuat koefisien tepat nol?", "Karena penalti nilai mutlak memiliki sudut di titik nol; solusi sering jatuh tepat di sudut itu."),
   ("Bagaimana bila prediktor berkelompok dan saling berkorelasi?", "Elastic net lebih tepat karena cenderung memilih kelompok prediktor itu bersama-sama.")])

X("elastic-net",
  "Dalam data ekspresi gen, ribuan gen diukur pada puluhan sampel, dan gen-gen yang bekerja bersama sangat berkorelasi. LASSO cenderung memilih satu gen dari setiap kelompok secara acak, sedangkan ridge tidak memilih sama sekali. Elastic net menggabungkan keduanya: memilih variabel sekaligus mempertahankan kelompok yang berkorelasi.",
  ["Kolom Y dan banyak kolom X numerik.",
   "Atur rasio L1 (α): 0 = ridge, 1 = LASSO, nilai di antaranya = campuran. Nilai 0,5 adalah titik awal yang wajar.",
   "λ dipilih otomatis dengan validasi silang."],
  [("Koefisien", "Sebagian koefisien bisa nol (dari komponen L1), dan prediktor yang berkorelasi cenderung mendapat koefisien serupa (dari komponen L2)."),
   ("Perbandingan dengan OLS", "Besarnya penyusutan setiap koefisien."),
   ("Jalur validasi silang", "Galat untuk berbagai λ pada α yang dipilih; coba beberapa α dan bandingkan galat minimumnya."),
   ("Nilai aktual dan prediksi", "Kecocokan model.")],
  ["Hanya mencoba satu nilai α.",
   "Membandingkan koefisien dari perangkat lunak berbeda tanpa memperhatikan parameterisasi penaltinya.",
   "Menafsirkan koefisien sebagai pengaruh yang tak bias."],
  "Contoh kalimat: “Elastic net (α = 0,5; λ dipilih dengan validasi silang 10 lipatan) mempertahankan 14 prediktor, termasuk tiga kelompok variabel yang saling berkorelasi, dengan galat prediksi validasi silang 12% lebih kecil daripada LASSO.”",
  [("Bagaimana memilih α?", "Coba beberapa nilai (misalnya 0,1; 0,5; 0,9) dengan pembagian lipatan validasi silang yang sama, lalu pilih yang galatnya terkecil."),
   ("Kapan elastic net lebih baik daripada LASSO?", "Bila prediktor berkelompok dan saling berkorelasi, atau jumlah prediktor jauh lebih besar daripada jumlah pengamatan.")])

X("principal-component-regression-pcr",
  "Seorang peneliti mengukur 15 dimensi tubuh ternak yang semuanya saling berkorelasi untuk memprediksi bobot karkas. Daripada memakai 15 prediktor yang tumpang tindih, PCR merangkumnya menjadi beberapa komponen utama yang tidak saling berkorelasi, lalu meregresikan bobot karkas pada komponen-komponen itu.",
  ["Kolom Y dan banyak kolom X numerik.",
   "Isi jumlah komponen dengan 0 agar dipilih otomatis melalui validasi silang.",
   "Prediktor dibakukan sebelum komponen dibentuk."],
  [("Ragam per komponen", "Proporsi ragam prediktor yang dijelaskan setiap komponen dan kumulatifnya."),
   ("Loading komponen", "Bobot setiap prediktor dalam komponen; loading yang besar menunjukkan prediktor yang membentuk komponen itu."),
   ("Koefisien", "Dikembalikan ke skala prediktor asli agar dapat dibandingkan dengan OLS."),
   ("Perbandingan dengan OLS", "Seberapa stabil koefisien PCR dibandingkan koefisien OLS yang terganggu kolinearitas.")],
  ["Memilih jumlah komponen hanya dari proporsi ragam prediktor, padahal komponen kecil bisa saja penting untuk Y.",
   "Menafsirkan komponen tanpa melihat loading-nya.",
   "Lupa bahwa koefisien PCR bias karena sebagian informasi dibuang."],
  "Contoh kalimat: “PCR dengan tiga komponen utama (menjelaskan 89% ragam lima belas dimensi tubuh) dipilih melalui validasi silang dan menghasilkan R² prediksi 0,82. Komponen pertama mencerminkan ukuran tubuh secara umum.”",
  [("PCR atau PLS?", "PLS membentuk komponen dengan memperhatikan Y, sehingga biasanya butuh lebih sedikit komponen untuk prediksi yang sama baiknya."),
   ("Apakah PCR sama dengan analisis komponen utama?", "PCR = analisis komponen utama pada X, lalu regresi Y pada skor komponennya.")])

X("partial-least-squares-pls",
  "Laboratorium pangan ingin memprediksi kadar protein tepung dari spektrum inframerah dekat (NIR) dengan ratusan panjang gelombang, padahal sampelnya hanya puluhan. OLS tidak mungkin dipakai karena prediktor lebih banyak dari pengamatan. PLS membentuk beberapa komponen yang sekaligus merangkum spektrum dan berhubungan erat dengan kadar protein.",
  ["Kolom Y dan banyak kolom X numerik; jumlah X boleh melebihi jumlah pengamatan.",
   "Isi jumlah komponen dengan 0 agar dipilih otomatis melalui validasi silang.",
   "Prediktor dibakukan secara otomatis."],
  [("Koefisien", "Koefisien regresi pada skala prediktor asli dari model dengan jumlah komponen terpilih."),
   ("VIP", "Variable Importance in Projection: prediktor dengan VIP di atas 1 umumnya dianggap penting, di bawah sekitar 0,8 kurang penting."),
   ("Perbandingan dengan OLS", "Bila OLS dapat dihitung, bandingkan kestabilan koefisiennya."),
   ("Nilai aktual dan prediksi", "Plot aktual lawan prediksi; titik yang menempel di garis diagonal menandakan prediksi baik.")],
  ["Memakai terlalu banyak komponen sehingga model menghafal data latih.",
   "Menilai model hanya dari R² data latih tanpa validasi silang atau data uji.",
   "Menafsirkan VIP sebagai uji signifikansi."],
  "Contoh kalimat: “Model PLS dengan empat komponen (dipilih melalui validasi silang) memprediksi kadar protein dengan RMSECV 0,31% dan R² validasi silang 0,93. Panjang gelombang di sekitar 2.180 nm memiliki VIP tertinggi.”",
  [("Apa beda PLS dengan PCR?", "PCR membentuk komponen dari X saja; PLS memilih arah yang memaksimumkan kovarians dengan Y."),
   ("Apakah PLS dapat menangani beberapa Y?", "Ya, PLS2 memodelkan beberapa respon sekaligus; kalkulator ini menangani satu Y (PLS1).")])
